use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn one_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn render(composed: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(&one_line(&composed.date));
    out.push_str("\n\n");

    let overview = composed.overview.trim();
    if !overview.is_empty() {
        out.push_str(overview);
        out.push_str("\n\n");
    }

    let mut entries: Vec<&ItemVerdict> = composed.entries.iter().collect();
    entries.sort_by_key(|e| importance_rank(e.importance));

    if entries.is_empty() {
        out.push_str("No items made the digest today.\n");
    } else {
        for (n, e) in entries.iter().enumerate() {
            out.push_str(&format!(
                "{}. [{} / {}] {}\n",
                n + 1,
                importance_label(e.importance),
                category_label(e.category),
                one_line(&e.title)
            ));
            let feed = one_line(&e.feed);
            if !feed.is_empty() {
                out.push_str("   from: ");
                out.push_str(&feed);
                out.push('\n');
            }
            let link = one_line(&e.link);
            if !link.is_empty() {
                out.push_str("   ");
                out.push_str(&link);
                out.push('\n');
            }
            let summary = e.summary.trim();
            if !summary.is_empty() {
                out.push_str("   ");
                out.push_str(&one_line(summary));
                out.push('\n');
            }
            out.push('\n');
        }
    }

    out.push_str(&format!(
        "({} items considered, {} included)\n",
        composed.considered.len(),
        composed.entries.len()
    ));
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);

        let mut published = false;
        for _ in 0..3 {
            if notifier::notify(&message) {
                published = true;
                break;
            }
        }

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
